@Test
public void combineByKey() {
    JavaRDD<Integer> originalRDD = sc.parallelize(Arrays.asList(1, 2, 3, 4, 5, 6));
    Function<Integer, Integer> keyFunction = v1 -> v1 % 3;
    Function<Integer, Integer> createCombinerFunction = v1 -> v1;
    Function2<Integer, Integer, Integer> mergeValueFunction = (v1, v2) -> v1 + v2;
    JavaPairRDD<Integer, Integer> combinedRDD = originalRDD.keyBy(keyFunction).combineByKey(createCombinerFunction, mergeValueFunction, mergeValueFunction);
    Map<Integer, Integer> results = combinedRDD.collectAsMap();
    ImmutableMap<Integer, Integer> expected = ImmutableMap.of(0, 9, 1, 5, 2, 7);
    assertEquals(expected, results);
    Partitioner defaultPartitioner = Partitioner.defaultPartitioner(combinedRDD.rdd(), JavaConverters.collectionAsScalaIterableConverter(Collections.<RDD<?>>emptyList()).asScala().toSeq());
    combinedRDD = originalRDD.keyBy(keyFunction).combineByKey(createCombinerFunction, mergeValueFunction, mergeValueFunction, defaultPartitioner, false, new KryoSerializer(new SparkConf()));
    results = combinedRDD.collectAsMap();
    assertEquals(expected, results);
}

