    final scala.collection.Map<String, Object> sKafkaParams = JavaConverters.mapAsScalaMapConverter(kafkaParams).asScala();
    final Map<TopicPartition, Long> offsets = new HashMap<>();
    offsets.put(tp1, 23L);
    final scala.collection.Map<TopicPartition, Object> sOffsets = JavaConverters.mapAsScalaMapConverter(offsets).asScala().mapValues(new scala.runtime.AbstractFunction1<Long, Object>() {

        @Override
        public Object apply(Long x) {
            return (Object) x;
        }
    });
    final ConsumerStrategy<String, String> sub1 = ConsumerStrategies.Subscribe(sTopics, sKafkaParams, sOffsets);
    final ConsumerStrategy<String, String> sub2 = ConsumerStrategies.Subscribe(sTopics, sKafkaParams);
