    final ConsumerStrategy<String, String> psub1 = ConsumerStrategies.SubscribePattern(pat, sKafkaParams, sOffsets);
    final ConsumerStrategy<String, String> psub2 = ConsumerStrategies.SubscribePattern(pat, sKafkaParams);
    final ConsumerStrategy<String, String> psub3 = ConsumerStrategies.SubscribePattern(pat, kafkaParams, offsets);
    final ConsumerStrategy<String, String> psub4 = ConsumerStrategies.SubscribePattern(pat, kafkaParams);
    Assert.assertEquals(psub1.executorKafkaParams().get("bootstrap.servers"), psub3.executorKafkaParams().get("bootstrap.servers"));
    final ConsumerStrategy<String, String> asn1 = ConsumerStrategies.Assign(sParts, sKafkaParams, sOffsets);
    final ConsumerStrategy<String, String> asn2 = ConsumerStrategies.Assign(sParts, sKafkaParams);
    final ConsumerStrategy<String, String> asn3 = ConsumerStrategies.Assign(parts, kafkaParams, offsets);
