@Test
public void randomizedStressTest() {
    int size = 65536;
    Random rand = new Random();
    // A set used to track collision rate.
    Set<Integer> hashcodes = new HashSet<>();
    for (int i = 0; i < size; i++) {
        int vint = rand.nextInt();
        long lint = rand.nextLong();
        Assert.assertEquals(HiveHasher.hashInt(vint), HiveHasher.hashInt(vint));
        Assert.assertEquals(HiveHasher.hashLong(lint), HiveHasher.hashLong(lint));
        hashcodes.add(HiveHasher.hashLong(lint));
    }
    // A very loose bound.
    Assert.assertTrue(hashcodes.size() > size * 0.95);
}

@Test
public void randomizedStressTestBytes() {
    int size = 65536;
    Random rand = new Random();
    // A set used to track collision rate.
    Set<Integer> hashcodes = new HashSet<>();
    for (int i = 0; i < size; i++) {
        int byteArrSize = rand.nextInt(100) * 8;
        byte[] bytes = new byte[byteArrSize];
        rand.nextBytes(bytes);
        Assert.assertEquals(HiveHasher.hashUnsafeBytes(bytes, Platform.BYTE_ARRAY_OFFSET, byteArrSize), HiveHasher.hashUnsafeBytes(bytes, Platform.BYTE_ARRAY_OFFSET, byteArrSize));
        hashcodes.add(HiveHasher.hashUnsafeBytes(bytes, Platform.BYTE_ARRAY_OFFSET, byteArrSize));
    }
    // A very loose bound.
    Assert.assertTrue(hashcodes.size() > size * 0.95);
}

@Test
public void randomizedStressTestPaddedStrings() {
    int size = 64000;
    // A set used to track collision rate.
    Set<Integer> hashcodes = new HashSet<>();
    for (int i = 0; i < size; i++) {
        int byteArrSize = 8;
        byte[] strBytes = String.valueOf(i).getBytes(StandardCharsets.UTF_8);
        byte[] paddedBytes = new byte[byteArrSize];
        System.arraycopy(strBytes, 0, paddedBytes, 0, strBytes.length);
        Assert.assertEquals(HiveHasher.hashUnsafeBytes(paddedBytes, Platform.BYTE_ARRAY_OFFSET, byteArrSize), HiveHasher.hashUnsafeBytes(paddedBytes, Platform.BYTE_ARRAY_OFFSET, byteArrSize));
        hashcodes.add(HiveHasher.hashUnsafeBytes(paddedBytes, Platform.BYTE_ARRAY_OFFSET, byteArrSize));
    }
    // A very loose bound.
    Assert.assertTrue(hashcodes.size() > size * 0.95);
}

