    Assert.assertEquals(0xAC75FDA2929B17EFL, XXH64.hashUnsafeBytes(BUFFER, Platform.BYTE_ARRAY_OFFSET, 0, PRIME));
    Assert.assertEquals(0x4FCE394CC88952D8L, hasher.hashUnsafeBytes(BUFFER, Platform.BYTE_ARRAY_OFFSET, 1));
    Assert.assertEquals(0x739840CB819FA723L, XXH64.hashUnsafeBytes(BUFFER, Platform.BYTE_ARRAY_OFFSET, 1, PRIME));
    // These tests currently fail in a big endian environment because the test data and expected
    // answers are generated with little endian the assumptions. We could revisit this when Platform
    // becomes endian aware.
    if (ByteOrder.nativeOrder() == ByteOrder.LITTLE_ENDIAN) {
        Assert.assertEquals(0x9256E58AA397AEF1L, hasher.hashUnsafeBytes(BUFFER, Platform.BYTE_ARRAY_OFFSET, 4));
        Assert.assertEquals(0x9D5FFDFB928AB4BL, XXH64.hashUnsafeBytes(BUFFER, Platform.BYTE_ARRAY_OFFSET, 4, PRIME));
