@Test
public void testGroupBy() {
    List<String> data = Arrays.asList("a", "foo", "bar");
    Dataset<String> ds = spark.createDataset(data, Encoders.STRING());
    KeyValueGroupedDataset<Integer, String> grouped = ds.groupByKey((MapFunction<String, Integer>) String::length, Encoders.INT());
    Dataset<String> mapped = grouped.mapGroups((MapGroupsFunction<Integer, String, String>) (key, values) -> {
        StringBuilder sb = new StringBuilder(key.toString());
        while (values.hasNext()) {
            sb.append(values.next());
        }
        return sb.toString();
    }, Encoders.STRING());
    Assert.assertEquals(asSet("1a", "3foobar"), toSet(mapped.collectAsList()));
    Dataset<String> flatMapped = grouped.flatMapGroups((FlatMapGroupsFunction<Integer, String, String>) (key, values) -> {
        StringBuilder sb = new StringBuilder(key.toString());
        while (values.hasNext()) {
            sb.append(values.next());
        }
        return Collections.singletonList(sb.toString()).iterator();
    }, Encoders.STRING());
    Assert.assertEquals(asSet("1a", "3foobar"), toSet(flatMapped.collectAsList()));
    Dataset<String> mapped2 = grouped.mapGroupsWithState((MapGroupsWithStateFunction<Integer, String, Long, String>) (key, values, s) -> {
        StringBuilder sb = new StringBuilder(key.toString());
        while (values.hasNext()) {
            sb.append(values.next());
        }
        return sb.toString();
    }, Encoders.LONG(), Encoders.STRING());
    Assert.assertEquals(asSet("1a", "3foobar"), toSet(mapped2.collectAsList()));
    Dataset<String> flatMapped2 = grouped.flatMapGroupsWithState((FlatMapGroupsWithStateFunction<Integer, String, Long, String>) (key, values, s) -> {
        StringBuilder sb = new StringBuilder(key.toString());
        while (values.hasNext()) {
            sb.append(values.next());
        }
        return Collections.singletonList(sb.toString()).iterator();
    }, OutputMode.Append(), Encoders.LONG(), Encoders.STRING(), GroupStateTimeout.NoTimeout());
    Assert.assertEquals(asSet("1a", "3foobar"), toSet(flatMapped2.collectAsList()));
    Dataset<Tuple2<Integer, String>> reduced = grouped.reduceGroups((ReduceFunction<String>) (v1, v2) -> v1 + v2);
    Assert.assertEquals(asSet(tuple2(1, "a"), tuple2(3, "foobar")), toSet(reduced.collectAsList()));
    List<Integer> data2 = Arrays.asList(2, 6, 10);
    Dataset<Integer> ds2 = spark.createDataset(data2, Encoders.INT());
    KeyValueGroupedDataset<Integer, Integer> grouped2 = ds2.groupByKey((MapFunction<Integer, Integer>) v -> v / 2, Encoders.INT());
    Dataset<String> cogrouped = grouped.cogroup(grouped2, (CoGroupFunction<Integer, String, Integer, String>) (key, left, right) -> {
        StringBuilder sb = new StringBuilder(key.toString());
        while (left.hasNext()) {
            sb.append(left.next());
        }
        sb.append("#");
        while (right.hasNext()) {
            sb.append(right.next());
        }
        return Collections.singletonList(sb.toString()).iterator();
    }, Encoders.STRING());
    Assert.assertEquals(asSet("1a#2", "3foobar#6", "5#10"), toSet(cogrouped.collectAsList()));
}

